#sliders{overflow-y:auto;scrollbar-width:thin;padding-right:4px;margin-bottom:10px}
.ctl{margin:7px 0}
.ctl label{display:flex;justify-content:space-between;font-size:10px;color:var(--dim);letter-spacing:.06em}
.ctl label output{color:var(--amber2)}
input[type=range]{width:100%;height:14px;-webkit-appearance:none;background:transparent;cursor:ew-resize}
input[type=range]::-webkit-slider-runnable-track{height:2px;background:rgba(255,255,255,.16)}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:9px;height:9px;border-radius:50%;
  background:var(--amber2);box-shadow:0 0 8px rgba(255,170,80,.9);margin-top:-3.5px}
input[type=range]::-moz-range-track{height:2px;background:rgba(255,255,255,.16)}
input[type=range]::-moz-range-thumb{border:0;width:9px;height:9px;border-radius:50%;background:var(--amber2)}

.row-btns{display:flex;gap:6px}
.row-btns button{flex:1;font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--amber2);
  background:rgba(255,180,94,.07);border:1px solid var(--line);border-radius:6px;padding:7px 0;cursor:pointer;
  transition:background .15s,color .15s}
.row-btns button:hover{background:rgba(255,180,94,.22);color:#fff}

footer#hudBottom{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;flex-wrap:wrap;gap:8px 18px;
  justify-content:center;padding:9px 12px;font-size:10px;color:var(--dim);letter-spacing:.12em;
  pointer-events:none;background:linear-gradient(0deg,rgba(0,0,0,.6),transparent)}
footer b{color:var(--amber2);font-weight:600}

/* ---------- help ---------- */
#helpOverlay{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;
  background:rgba(0,0,0,.66)}
.help-card{width:min(560px,92vw);background:var(--panel);border:1px solid var(--line);border-radius:12px;
  padding:20px 22px;backdrop-filter:blur(12px)}
.help-card h2{color:var(--amber);letter-spacing:.28em;font-size:12px;margin-bottom:12px}
.help-card table{width:100%;border-collapse:collapse;font-size:11px}
.help-card td{padding:4px 6px;border-bottom:1px dashed rgba(255,255,255,.08)}
.help-card td:first-child{color:var(--amber2);white-space:nowrap;width:110px}
.help-card p{margin-top:12px;font-size:10.5px;color:var(--dim);line-height:1.6}
.help-card code{color:#fff}
.help-card button{margin-top:14px;width:100%;font-family:var(--mono);padding:8px 0;letter-spacing:.2em;
  color:#fff;background:rgba(255,180,94,.16);border:1px solid var(--line);border-radius:8px;cursor:pointer}

body.ui-hidden .panel,body.ui-hidden header,body.ui-hidden footer{display:none}

@media (max-width:900px){
  aside#telemetry{top:auto;bottom:44px;left:10px;width:178px;padding:9px}
  section#ctrl{width:230px;right:10px;top:56px}
  #hint{display:none}
}
@media (max-width:620px){
  aside#telemetry,#hudStats .stat:nth-child(n+3){display:none}
  section#ctrl{max-height:52vh}
}

// GARGANTUA — shared uniforms, quality profiles, presets (pure data + tiny math).
export const QUALITY = {
  low:  { steps: 96,  extra: 0, sub: 1.00, resScale: 0.62, label: 'LOW'  },
  med:  { steps: 192, extra: 0, sub: 1.00, resScale: 0.80, label: 'MED'  },
  high: { steps: 320, extra: 2, sub: 2.00, subOn: true, resScale: 1.00, label: 'HIGH' }
};

// 21 live parameters — every one is a real uniform read by the shader.
export const PARAM_DEFS = [
  ['diskDensity',   'disk density',      0.0, 3.0, 0.01, 1.30],
  ['diskInner',     'disk inner r',      3.0, 9.0, 0.05, 6.0],
  ['diskOuter',     'disk outer r',     10.0,26.0, 0.25, 15.5],
  ['diskThick',     'disk thickness',    0.02,0.60,0.01, 0.16],
  ['diskTemp',      'temperature K',   2000,14000,100,  7200],
  ['spinSpeed',     'turbulence speed',  0.0, 2.0, 0.01, 0.55],
  ['turbScale',     'turbulence scale',  0.5, 8.0, 0.05, 2.6],
  ['turbGain',      'turbulence gain',   0.0, 2.0, 0.01, 0.85],
  ['starGain',      'star gain',         0.0, 2.5, 0.01, 1.0],
  ['milkyGain',     'milky way gain',    0.0, 2.0, 0.01, 0.55],
  ['dopplerAmt',    'Doppler beaming',   0.0, 1.0, 0.01, 0.92],
  ['gravRedshift',  'redshift',          0.0, 1.0, 0.01, 1.0],
  ['bloomStrength', 'bloom strength',    0.0, 2.0, 0.01, 0.62],
  ['bloomRadius',   'bloom radius',      0.4, 2.4, 0.01, 0.95],
  ['exposure',      'exposure EV',      -2.5, 2.5, 0.05, 0.55],
  ['grainAmt',      'film grain',        0.0, 0.20,0.002,0.035],
  ['aberration',    'chromatic aberr.',  0.0, 3.0, 0.01, 0.75],
  ['vignette',      'vignette',          0.0, 1.5, 0.01, 0.72],
