:root{
  --amber:#ffb45e; --amber2:#ffd9a0; --ink:#05070c;
  --panel:rgba(8,11,18,.72); --line:rgba(255,180,94,.28);
  --txt:#dfe6f2; --dim:#8b95a8;
  --mono:"SFMono-Regular",ui-monospace,"Cascadia Mono",Consolas,Menlo,monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;background:#000;color:var(--txt);overflow:hidden;
  font-family:var(--mono);-webkit-font-smoothing:antialiased}
canvas#gl{position:fixed;inset:0;width:100%;height:100%;display:block;z-index:0}

/* ---------- boot ---------- */
#boot{position:fixed;inset:0;z-index:60;display:flex;align-items:center;justify-content:center;
  background:radial-gradient(120% 120% at 50% 45%,#0a0e16 0%,#000 75%);
  transition:opacity .7s ease,visibility .7s}
#boot.gone{opacity:0;visibility:hidden}
.boot-inner{text-align:center}
.boot-title{font-size:clamp(26px,5vw,54px);letter-spacing:.42em;text-indent:.42em;
  color:var(--amber2);text-shadow:0 0 26px rgba(255,150,60,.55)}
.boot-sub{margin-top:.6em;font-size:12px;letter-spacing:.3em;color:var(--dim)}
.boot-bar{width:min(320px,60vw);height:2px;background:rgba(255,255,255,.08);margin:26px auto 10px;overflow:hidden}
.boot-bar i{display:block;height:100%;width:4%;background:linear-gradient(90deg,var(--amber),#fff);
  box-shadow:0 0 12px var(--amber);transition:width .25s ease}
#bootMsg{font-size:11px;color:var(--dim);letter-spacing:.14em}

/* ---------- panels ---------- */
.panel{position:fixed;z-index:20;background:var(--panel);border:1px solid var(--line);
  border-radius:10px;padding:12px 14px;backdrop-filter:blur(9px) saturate(1.15)}
.panel h2{font-size:11px;letter-spacing:.32em;color:var(--amber);font-weight:600;margin-bottom:9px}
.panel h2 em{color:var(--dim);font-style:normal;letter-spacing:.08em}

header#hudTop{position:fixed;top:0;left:0;right:0;z-index:20;display:flex;justify-content:space-between;
  align-items:center;padding:10px 16px;pointer-events:none;
  background:linear-gradient(180deg,rgba(0,0,0,.62),transparent)}
#brand{font-size:13px;letter-spacing:.34em;color:var(--amber2)}
#brand span{color:var(--dim);letter-spacing:.2em;font-size:10px}
#hudStats{display:flex;gap:14px;font-size:10px;color:var(--dim);letter-spacing:.12em}
.stat b{color:var(--txt);font-weight:600}

aside#telemetry{left:16px;top:64px;width:212px;font-size:11px}
#telemetry dl{display:grid;grid-template-columns:auto auto;gap:3px 10px}
#telemetry dt{color:var(--dim)} #telemetry dd{text-align:right;color:var(--amber2)}
#telemetry dd b{color:#fff;font-weight:600}

section#ctrl{right:16px;top:64px;width:264px;max-height:calc(100vh - 170px);
  display:flex;flex-direction:column}
#sliders{overflow-y:auto;scrollbar-width:thin;padding-right:4px;margin-bottom:10px}
.ctl{margin:7px 0}
.ctl label{display:flex;justify-content:space-between;font-size:10px;color:var(--dim);letter-spacing:.06em}
.ctl label output{color:var(--amber2)}
input[type=range]{width:100%;height:14px;-webkit-appearance:none;background:transparent;cursor:ew-resize}
input[type=range]::-webkit-slider-runnable-track{height:2px;background:rgba(255,255,255,.16)}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:9px;height:9px;border-radius:50%;
  background:var(--amber2);box-shadow:0 0 8px rgba(255,170,80,.9);margin-top:-3.5px}
input[type=range]::-moz-range-track{height:2px;background:rgba(255,255,255,.16)}
input[type=range]::-moz-range-thumb{border:0;width:9px;height:9px;border-radius:50%;background:var(--amber2)}

.row-btns{display:flex;gap:6px}
.row-btns button{flex:1;font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--amber2);
  background:rgba(255,180,94,.07);border:1px solid var(--line);border-radius:6px;padding:7px 0;cursor:pointer;
  transition:background .15s,color .15s}
.row-btns button:hover{background:rgba(255,180,94,.22);color:#fff}

footer#hudBottom{position:fixed;left:0;right:0;bottom:0;z-index:20;display:flex;flex-wrap:wrap;gap:8px 18px;
  justify-content:center;padding:9px 12px;font-size:10px;color:var(--dim);letter-spacing:.12em;
  pointer-events:none;background:linear-gradient(0deg,rgba(0,0,0,.6),transparent)}
footer b{color:var(--amber2);font-weight:600}

/* ---------- help ---------- */
#helpOverlay{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;
  background:rgba(0,0,0,.66)}
.help-card{width:min(560px,92vw);background:var(--panel);border:1px solid var(--line);border-radius:12px;
  padding:20px 22px;backdrop-filter:blur(12px)}
.help-card h2{color:var(--amber);letter-spacing:.28em;font-size:12px;margin-bottom:12px}
.help-card table{width:100%;border-collapse:collapse;font-size:11px}
.help-card td{padding:4px 6px;border-bottom:1px dashed rgba(255,255,255,.08)}
.help-card td:first-child{color:var(--amber2);white-space:nowrap;width:110px}
.help-card p{margin-top:12px;font-size:10.5px;color:var(--dim);line-height:1.6}
.help-card code{color:#fff}
.help-card button{margin-top:14px;width:100%;font-family:var(--mono);padding:8px 0;letter-spacing:.2em;
  color:#fff;background:rgba(255,180,94,.16);border:1px solid var(--line);border-radius:8px;cursor:pointer}

body.ui-hidden .panel,body.ui-hidden header,body.ui-hidden footer{display:none}

@media (max-width:900px){
  aside#telemetry{top:auto;bottom:44px;left:10px;width:178px;padding:9px}
  section#ctrl{width:230px;right:10px;top:56px}
  #hint{display:none}
}
@media (max-width:620px){
  aside#telemetry,#hudStats .stat:nth-child(n+3){display:none}
  section#ctrl{max-height:52vh}
}

// GARGANTUA — shared uniforms, quality profiles, presets (pure data + tiny math).
export const QUALITY = {
  low:  { steps: 96,  extra: 0, sub: 1.00, resScale: 0.62, label: 'LOW'  },
  med:  { steps: 192, extra: 0, sub: 1.00, resScale: 0.80, label: 'MED'  },
  high: { steps: 320, extra: 2, sub: 2.00, subOn: true, resScale: 1.00, label: 'HIGH' }
};

// 21 live parameters — every one is a real uniform read by the shader.
export const PARAM_DEFS = [
  ['diskDensity',   'disk density',      0.0, 3.0, 0.01, 1.30],
  ['diskInner',     'disk inner r',      3.0, 9.0, 0.05, 6.0],
  ['diskOuter',     'disk outer r',     10.0,26.0, 0.25, 15.5],
  ['diskThick',     'disk thickness',    0.02,0.60,0.01, 0.16],
  ['diskTemp',      'temperature K',   2000,14000,100,  7200],
  ['spinSpeed',     'turbulence speed',  0.0, 2.0, 0.01, 0.55],
  ['turbScale',     'turbulence scale',  0.5, 8.0, 0.05, 2.6],
  ['turbGain',      'turbulence gain',   0.0, 2.0, 0.01, 0.85],
  ['starGain',      'star gain',         0.0, 2.5, 0.01, 1.0],
  ['milkyGain',     'milky way gain',    0.0, 2.0, 0.01, 0.55],
  ['dopplerAmt',    'Doppler beaming',   0.0, 1.0, 0.01, 0.92],
  ['gravRedshift',  'redshift',          0.0, 1.0, 0.01, 1.0],
  ['bloomStrength', 'bloom strength',    0.0, 2.0, 0.01, 0.62],
  ['bloomRadius',   'bloom radius',      0.4, 2.4, 0.01, 0.95],
  ['exposure',      'exposure EV',      -2.5, 2.5, 0.05, 0.55],
  ['grainAmt',      'film grain',        0.0, 0.20,0.002,0.035],
  ['aberration',    'chromatic aberr.',  0.0, 3.0, 0.01, 0.75],
  ['vignette',      'vignette',          0.0, 1.5, 0.01, 0.72],
  ['blackFloor',    'black floor',       0.0, 0.06,0.001,0.004],
  ['timeWarp',      'time dilation fx',  0.0, 2.0, 0.01, 1.0],
  ['camFov',        'camera FOV°',      22.0,100.0,0.5,  52.0]
];

export function defaultParams(){
  const o = {};
  for (const [k,,,,,v] of PARAM_DEFS) o[k] = v;
  return o;
}

export const PRESETS = {
  interstellar: {
    name:'INTERSTELLAR',
    p:{ diskDensity:1.35,diskInner:6.0,diskOuter:15.5,diskThick:0.16,diskTemp:7200,
        spinSpeed:0.55,turbScale:2.6,turbGain:0.85,starGain:1.0,milkyGain:0.55,
        dopplerAmt:0.92,gravRedshift:1.0,bloomStrength:0.62,bloomRadius:0.95,
        exposure:0.55,grainAmt:0.035,aberration:0.75,vignette:0.72,blackFloor:0.004,
        timeWarp:1.0,camFov:52.0 }
  },
  photon: {
    name:'PHOTON RING',
    p:{ diskDensity:0.55,diskInner:6.0,diskOuter:13.0,diskThick:0.07,diskTemp:9500,
        spinSpeed:0.18,turbScale:3.4,turbGain:0.45,starGain:0.8,milkyGain:0.28,
        dopplerAmt:0.55,gravRedshift:1.0,bloomStrength:1.15,bloomRadius:0.65,
        exposure:0.85,grainAmt:0.03,aberration:1.25,vignette:0.55,blackFloor:0.002,
        timeWarp:1.0,camFov:38.0 }
  },
  edgeon: {
    name:'EDGE-ON BLADE',
    p:{ diskDensity:1.7,diskInner:6.0,diskOuter:17.5,diskThick:0.05,diskTemp:6400,
        spinSpeed:0.75,turbScale:3.8,turbGain:1.15,starGain:0.7,milkyGain:0.4,
        dopplerAmount:undefined,dopplerAmt:1.0,gravRedshift:1.0,bloomStrength:0.5,
        bloomRadius:1.25,exposure:0.3,grainAmt:0.04,aberration:1.6,vignette:0.85,
        blackFloor:0.006,timeWarp:1.0,camFov:46.0 }
  },
  abyss: {
    name:'ABYSS',
    p:{ diskDensity:0.22,diskInner:7.0,diskOuter:11.0,diskThick:0.30,diskTemp:3800,
        spinSpeed:0.12,turbScale:1.6,turbGain:0.55,starGain:1.6,milkyGain:1.15,
        dopplerAmt:0.35,gravRedshift:1.0,bloomStrength:0.42,bloomRadius:1.35,
        exposure:0.15,grainAmt:0.055,aberration:0.4,vignette:1.05,blackFloor:0.010,
        timeWarp:0.6,camFov:58.0 }
  }
};

export const CAMERA_PATHS = [
  { id:'orbit',    name:'ORBIT (free)' },
  { id:'slowspin', name:'CINEMATIC · SLOW SPIN' },
  { id:'grazing',  name:'CINEMATIC · GRAZING PASS' },
  { id:'plunge',   name:'CINEMATIC · PLUNGE & RECOIL' },
  { id:'rise',     name:'CINEMATIC · RISE OVER DISK' }
];

// GARGANTUA — GLSL programs. Scene pass integrates Schwarzschild null geodesics
// (velocity-Verlet on the exact Cartesian form  a = -3 h² x / r⁵  in M-units,
// r_s = 2M, photon sphere 3M, ISCO 6M). All output is linear HDR.

export const VERT = /* glsl */`
varying vec2 vUv;
void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }
`;

const DEFS = `
#define PI 3.141592653589793
#define ESC_R 46.0
`;

const LIB = /* glsl */`
float hash11(float p){ p = fract(p*0.1031); p *= p+33.33; p *= p+p; return fract(p); }
vec3 hash33(vec3 p){
  p = fract(p*vec3(0.1031,0.1030,0.0973));
  p += dot(p, p.yxz+33.33);
  return fract((p.xxy+p.yxx)*p.zyx);
}
float vnoise(vec3 p){
  vec3 i = floor(p), f = fract(p);
  f = f*f*(3.0-2.0*f);
  float n = mix(
    mix(mix(hash33(i+vec3(0,0,0)).x, hash33(i+vec3(1,0,0)).x, f.x),
        mix(hash33(i+vec3(0,1,0)).x, hash33(i+vec3(1,1,0)).x, f.x), f.y),
    mix(mix(hash33(i+vec3(0,0,1)).x, hash33(i+vec3(1,0,1)).x, f.x),
        mix(hash33(i+vec3(0,1,1)).x, hash33(i+vec3(1,1,1)).x, f.x), f.y), f.z);
  return n*n*(3.0-2.0*n)*2.0-0.30;   // centered, zero-mean-ish
}
float fbm(vec3 p){
  float a = 0.52, s = 0.0, norm = 0.0;
  for(int i=0;i<5;i++){ s += a*vnoise(p); norm += a; p = p*2.03 + 17.13; a *= 0.52; }
  return s/norm;
}
// Planckian locus approximation (Kelvin -> linear sRGB-ish)
vec3 blackbody(float K){
  float t = clamp(K, 1200.0, 22000.0)*0.01;
  float r = t<=66.0 ? 1.0 : clamp(1.29294*pow(t-60.0,-0.1332047), 0.0, 1.0);
  float g = t<=66.0 ? clamp(0.39008*log(t)-0.63184, 0.0, 1.0)
                    : clamp(1.12989*pow(t-60.0,-0.0755148), 0.0, 1.0);
  float b = t>=66.0 ? 1.0 : (t<=19.0 ? 0.0 : clamp(0.54320*log(t-10.0)-1.19625, 0.0, 1.0));
  return vec3(r,g,b);
}
mat3 rotY(float a){ float c=cos(a),s=sin(a); return mat3(c,0.,-s, 0.,1.,0., s,0.,c); }
`;

const SKY = /* glsl */`
uniform float uStarGain, uMilkyGain;

float starLayer(vec3 d, float scale, float gain){
  vec3 p = d*scale;
  vec3 c = floor(p);
  float m = 0.0;
  for(int x=-1;x<=1;x++) for(int y=-1;y<=1;y++) for(int z=-1;z<=1;z++){
    vec3 o = vec3(float(x),float(y),float(z));
    vec3 h = hash33(c+o);
    float mag = pow(h.y, 22.0);                 // sparse bright stars
    if(mag < 1e-4) continue;
    vec3 sp = c + o + 0.15 + 0.7*h;
    float dd = length(p - sp);
    m += exp(-dd*dd*(140.0+240.0*h.z)) * mag;
  }
  return m*gain;
}

vec3 skyColor(vec3 d){
  float st = starLayer(d, 34.0, 1.0)*1.5 + starLayer(d+vec3(7.31), 71.0, 0.55)*0.9
           + starLayer(d.zxy+vec3(3.7), 143.0, 0.30)*0.55;
  vec3 scol = vec3(0.78,0.85,1.0)*st + vec3(1.0,0.86,0.70)*starLayer(d.yzx+vec3(11.2),57.0,0.42);

  vec3 pole = normalize(vec3(0.32,0.86,0.39));
  vec3 core = normalize(vec3(-0.78,0.10,0.61));
  float band = exp(-pow(dot(d,pole)*2.35, 2.0)*3.2);
  float cloud = fbm(d*3.1+vec3(4.7))*0.5+0.5;
  float lanes = smoothstep(0.42,0.78, fbm(d*6.3+vec3(9.1))*0.5+0.5);
  float mw = band*(0.30+0.85*cloud)*(1.0-0.75*lanes);
  float coreGlow = pow(max(dot(d,core),0.0), 7.0)*band;
  vec3 mcol = mix(vec3(0.36,0.42,0.62), vec3(0.95,0.80,0.60), coreGlow*1.6+cloud*0.22);
  return (scol*1.15 + mcol*mw*1.35 + vec3(0.50,0.62,1.0)*coreGlow*0.55)
         * vec3(uStarGain*0.55+0.45) * vec3(1.0, 1.0, 1.05)
         + vec3(0.010,0.012,0.020);              // deep-space ambient floor
}
`;

const SCENE_BODY = /* glsl */`
uniform vec2  uRes;
uniform float uTime, uTanFov, uSteps, uDbg, uSeed, uAspect;
uniform vec3  uCamPos, uCamRight, uCamUp, uCamFwd;
uniform float uDiskDensity,uDiskInner,uDiskOuter,uDiskThick,uDiskTemp,
              uSpinSpeed,uTurbScale,uTurbGain,uDopplerAmt,uGravRedshift;
varying vec2 vUv;

${LIB}
${SKY}

void diskEmit(vec3 p, vec3 vel, float dt, inout vec3 acc, inout float trans,
              inout float gLast){
  float r = length(p.xz);
  float ri = uDiskInner, ro = uDiskOuter;
  if(r < ri || r > ro || trans < 0.004) return;
  float fr = (r-ri)/max(ro-ri, 1e-3);
  float H = uDiskThick*(0.30+0.85*fr) * (0.5+0.5*ri/r);
  float prof = exp(-0.5*(p.y/H)*(p.y/H));
  if(prof < 0.004) return;

  float ang = atan(p.z, p.x);
  float omega = 0.55*uSpinSpeed*pow(max(r,0.8), -1.5);
  vec3 rp = rotY(uTime*omega*6.0) * p;               // differential Keplerian shear
  float turb = fbm(vec3(rp.x, rp.z, p.y*2.6)*uTurbScale*0.55)*0.5+0.5;
  float streak = fbm(vec3(r*1.7, ang*2.0 + rp.x*0.20, p.y*4.0)*1.6)*0.5+0.5;
  float dens = prof * uDiskDensity *
      (0.22 + uTurbGain*(0.65*turb + 0.55*streak));

  float fall = pow(ri/r, 2.1);
  dens *= fall * smoothstep(ro, ro*0.70, r) * smoothstep(ri, ri*1.12, r) * 2.6;
  if(dens <= 0.0) return;

  float beta = clamp(inversesqrt(max(2.0*(r-1.0), 0.45)), 0.0, 0.985); // v/c, ISCO=0.5
  float gam  = inversesqrt(1.0-beta*beta);
  vec3 tangent = normalize(vec3(-p.z, 0.0, p.x));
  vec3 kphoton = -normalize(vel);
  float gd = 1.0/(gam*(1.0 - beta*dot(tangent,kphoton)));
  float gg = sqrt(max(1.0-1.0/r, 0.02));
  float g = mix(1.0, gd, uDopplerAmt) * mix(1.0, gg, uGravRedshift);
  gLast = g;

  float T = uDiskTemp * pow(ri/r, 0.75) * g;
  vec3 e = blackbody(T) * pow(max(g,0.02), 3.0);
  float e2 = dens*dt;
  acc   += e * e2 * trans * 2.35;
  trans *= exp(-dens*dt*1.35);
}

void main(){
  vec2 frag = vUv*uRes;
  vec2 jit = vec2(hash11(frag.x*12.9898+uSeed), hash11(frag.y*78.233+uSeed)) - 0.5;
  vec2 ndc = (frag+jit)/uRes*2.0 - 1.0;
  vec3 rd = normalize(uCamFwd + uCamRight*ndc.x*uTanFov*uAspect + uCamUp*ndc.y*uTanFov);
  vec3 p  = uCamPos;
  vec3 v  = rd;
  float h2 = length2(cross(p, v));

  vec3 acc = vec3(0.0);
  float trans = 1.0, minR = 1e4, gLast = 1.0, bend = 0.0;
  bool captured = false, escaped = false;
  float stepsUsed = 0.0;
  float prevY = p.y;

  for(int i=0;i<MAX_STEPS_LOOP;i++){
    if(float(i) >= uSteps){ escaped = false; break; }
    stepsUsed = float(i);
    float r = length(p);
    minR = min(minR, r);
    if(r < 1.02){ captured = true; break; }
    if(r > ESC_R && dot(p,v) > 0.0){ escaped = true; break; }

    float planeProx = exp(-p.y*p.y*10.0)
        * smoothstep(uDiskInner-2.5, uDiskInner, length(p.xz))
        * smoothstep(uDiskOuter+3.0, uDiskOuter, length(p.xz));
    float dt = clamp(0.05 + 0.16*(r-1.0), 0.022, 1.15) * mix(1.0, 0.40, planeProx);
    if(r < 3.2) dt = min(dt, 0.06 + 0.05*(r-1.0));

    vec3 a1 = -1.5*h2*p/pow(dot(p,p), 2.5);
    vec3 pn = p + v*dt + 0.5*a1*dt*dt;
    vec3 a2 = -1.5*h2*pn/pow(dot(pn,pn), 2.5);
    vec3 vn = v + 0.5*(a1+a2)*dt;

    bend += length(a2)*dt;
    if(planeProx > 0.02){
      diskEmit(pn, vn, dt, acc, trans, gLast);
    } else if(prevY*pn.y < 0.0){                     // thin-slab crossing guard
      for(int s=1;s<=3;s++){
        float f = float(s)/3.0;
        vec3 q = mix(p, pn, f);
        diskEmit(q, normalize(mix(v,vn,f)), dt/3.0, acc, trans, gLast);
      }
    }
    prevY = pn.y;
    p = pn; v = vn;
  }

  vec3 col;
  vec3 dirOut = normalize(v);
  if(captured){
    col = acc + vec3(0.0);
  } else {
    vec3 sky = escaped ? skyColor(dirOut) : vec3(0.0);
    float ring = exp(-pow((minR-1.5)*7.0, 2.0));
    col = acc + sky*trans + vec3(0.30,0.42,0.85)*ring*0.10*trans*(0.4+0.6*uDopplerAmt);
  }

  float dbg = floor(uDbg+0.5);
  if(dbg == 1.0) col = vec3(max(max(col.r,col.g),col.b));                       // HDR lum
  else if(dbg == 2.0) col = vec3(pow(stepsUsed/uSteps, 0.5), stepsUsed/uSteps*0.6, 0.15);
  else if(dbg == 3.0) col = blackbody(mix(2500.0, 14000.0, clamp((gLast-0.4)/1.4,0.0,1.0)))
                             * (acc.r+acc.g+acc.b > 0.0 ? 1.0 : 0.06);
  else if(dbg == 4.0) col = vec3(clamp((acc.r+acc.g+acc.b)*0.8, 0.0, 1.0));
  else if(dbg == 5.0) col = vec3(pow(clamp(bend*0.16,0.0,1.0), 0.7))*vec3(1.0,0.55,0.25);
  else if(dbg == 6.0) col = escaped ? dirOut*0.5+0.5 : vec3(0.0);
  else if(dbg == 7.0) col = vec3(exp(-pow((minR-1.5)*9.0, 2.0)));
  else if(dbg == 8.0) col = captured ? vec3(1.0,0.2,0.1) : vec3(0.02,0.05,0.09);
  else if(dbg == 9.0) col = escaped ? skyColor(dirOut) : vec3(0.0);

  gl_FragColor = vec4(col, 1.0);
}
`;

export const FRAG_SCENE = DEFS + SCENE_BODY;

/* ---------------- post chain (HDR -> bloom -> ACES composite) ------------- */

export const FRAG_BRIGHT = /* glsl */`
uniform sampler2D tSrc; uniform vec2 uTexel; uniform float uThreshold;
varying vec2 vUv;
void main(){
  vec3 c = texture2D(tSrc, vUv).rgb;
  float l = dot(c, vec3(0.2126,0.7152,0.0722));
  float knee = uThreshold*0.4;
  float w = smoothstep(uThreshold-knee, uThreshold+knee, l);
  gl_FragColor = vec4(c*w, 1.0);
}
`;

const BLUR = /* glsl */`
uniform sampler2D tSrc; uniform vec2 uTexel; uniform vec2 uDir; uniform float uRadius;
varying vec2 vUv;
void main(){
  vec2 o = uDir*uTexel*uRadius;
  vec3 s = texture2D(tSrc, vUv).rgb*0.227027;
  s += (texture2D(tSrc, vUv+o*1.3846).rgb + texture2D(tSrc, vUv-o*1.3846).rgb)*0.316216;
  s += (texture2D(tSrc, vUv+o*3.2308).rgb + texture2D(tSrc, vUv-o*3.2308).rgb)*0.070270;
  gl_FragColor = vec4(s, 1.0);
}
`;
export const FRAG_BLUR = BLUR;

export const FRAG_COMPOSITE = /* glsl */`
uniform sampler2D tScene, tBloom;
uniform vec2 uRes;
uniform float uTime,uBloomStr,uExposureEV,uGrain,uAberr,uVignette,uBlackFloor,uSeed;
varying vec2 vUv;

vec3 aces(vec3 x){
  const float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14;
  return clamp((x*(a*x+b))/(x*(c*x+d)+e), 0.0, 1.0);
}
float grain(vec2 uv, float t){
  vec3 h = vec3(uv, fract(t))*vec3(443.897,441.423,437.195);
  return fract(sin(dot(h, vec3(12.9898,78.233,37.719)))*43758.5453);
}
void main(){
  vec2 uv = vUv;
  vec2 d = uv-0.5;
  float r2 = dot(d,d);
  float ab = uAberr*0.0035*r2;
  vec3 c;
  c.r = texture2D(tScene, uv-d*ab).r;
  c.g = texture2D(tScene, uv).g;
  c.b = texture2D(tScene, uv+d*ab).b;
  vec3 bl = texture2D(tBloom, uv).rgb;
  c += bl*uBloomStr;

  c *= exp2(uExposureEV);
  c = aces(c);
  c = pow(c, vec3(1.0/2.2));

  float vig = 1.0 - uVignette*smoothstep(0.18, 0.92, sqrt(r2)*1.414);
  c *= vig;
  c += (grain(uv*uRes, uTime+uSeed)-0.5)*uGrain*(0.35+0.65*(1.0-c));
  c = c*(1.0-uBlackFloor) + uBlackFloor;
  gl_FragColor = vec4(clamp(c,0.0,1.0), 1.0);
}
`;

export function patchScene(src, maxSteps){
  return src.replace('__DEFS__', '')
            .replace('#define ESC_R', `#define MAX_STEPS_LOOP ${maxSteps|0}\n#define ESC_R`);
}

